[STAThread]static int Main(string[] args){Application.EnableVisualStyles();var h=(TrainerIntegrationHost)Activator.CreateInstance(typeof(TrainerIntegrationHost),true);RelayDeadbandExperiment experiment=null;try{
IntPtr handle=h.Handle;Call(h,"StartNative");((Timer)typeof(TrainerIntegrationHost).GetField("timer",flags).GetValue(h)).Stop();var mem=(Dictionary<string,IntPtr>)typeof(TrainerIntegrationHost).GetField("mem",flags).GetValue(h);var cars=(IntPtr[])typeof(TrainerIntegrationHost).GetField("cars",flags).GetValue(h);var train=(IntPtr)typeof(TrainerIntegrationHost).GetField("trainData",flags).GetValue(h);int count=Marshal.ReadInt32(train);var loc=mem["TLocParam"];inputLoc=loc;electrical=Array.IndexOf(args,"electrical")>=0;float step=float.Parse(args[0],System.Globalization.CultureInfo.InvariantCulture);bool candidate=Array.IndexOf(args,"candidate")>=0;bool warm=Array.IndexOf(args,"warm")>=0;bool ro1=Array.IndexOf(args,"ro1")>=0;if(ro1)Marshal.WriteByte(cars[0],0x19,1);bool headpl=Array.IndexOf(args,"headpl")>=0;if(headpl)Marshal.WriteByte(cars[0],0xf2,1);bool vr483a=Array.IndexOf(args,"vr483a")>=0;if(vr483a)Marshal.WriteByte(cars[0],0xe7,1);bool zr20=Array.IndexOf(args,"zr20")>=0;if(zr20)Marshal.Copy(BitConverter.GetBytes(20.0),0,IntPtr.Add(cars[0],0xd7),8);bool pilot1=Array.IndexOf(args,"pilot1")>=0;if(pilot1)Marshal.Copy(BitConverter.GetBytes(1.0),0,IntPtr.Add(cars[0],0xdf),8);bool secs1=Array.IndexOf(args,"secs1")>=0;if(secs1)Marshal.WriteByte(loc,4,1);if(candidate)experiment=new RelayDeadbandExperiment(.03,true);
