for(int n=1;n<=3000;n++){Cycle(h);float tm=F(cars[0],0),ur=F(loc,9),tc=F(loc,13);if(float.IsNaN(tm)||float.IsInfinity(tm)||float.IsNaN(ur)||float.IsInfinity(ur)||float.IsNaN(tc)||float.IsInfinity(tc))throw new Exception("Invalid pressure");if(n==300){settledUr=ur;settledTm=tm;}if(n>=300){minTm=Math.Min(minTm,tm);maxTm=Math.Max(maxTm,tm);minTc=Math.Min(minTc,tc);}if(n<=5||n%100==0)rows.Add(new{seconds=n*.1,pm=F(loc,5),zr=F(cars[0],8),sections=Marshal.ReadByte(loc,4),kvt=Marshal.ReadByte(loc,0x7e),release=Marshal.ReadByte(loc,0x8c),tm=tm,ur=ur,tc=tc,vr_tc=F(cars[0],4),tail_tc=F(cars[count-1],4),tail_tm=F(cars[count-1],0),head_rk=D(cars[0],0x71),head_zk=D(cars[0],0x69),head_ks=D(cars[0],0x61),head_dr=D(cars[0],0x79),tail_rk=D(cars[count-1],0x71),tail_zk=D(cars[count-1],0x69),tail_ks=D(cars[count-1],0x61),tail_dr=D(cars[count-1],0x79)});}
float finalUr=F(loc,9),finalTm=F(cars[0],0),finalTc=F(loc,13);bool testRelease=Array.IndexOf(args,"release")>=0;int releaseCycles=-1;float releasedTc=finalTc;if(testRelease){Marshal.WriteByte(loc,0x7d,2);for(int n=1;n<=3000;n++){Cycle(h);releasedTc=F(loc,13);if(float.IsNaN(releasedTc)||float.IsInfinity(releasedTc))throw new Exception("Invalid release pressure");if(releasedTc<.05f){releaseCycles=n;break;}}if(releaseCycles<0)throw new Exception("No locomotive release within300s");}var result=new{scope="Native pneumatic train small KM V step followed by KM IV for 300 seconds, no calibrated external leak; not a complete RE acceptance",sections=Marshal.ReadByte(loc,4),head_zr_volume=D(cars[0],0xd7),head_output_volume=D(cars[0],0xdf),head_vr_type=Marshal.ReadByte(cars[0],0xe7),head_ro=Marshal.ReadByte(cars[0],0x19),head_wagon_type=Marshal.ReadByte(cars[0],0xf2),release_test=testRelease,release_seconds=releaseCycles<0?(double?)null:releaseCycles*.1,released_tc=releasedTc,electrical_cycle=electrical,electrical_faults=(int)typeof(TrainerIntegrationHost).GetField("electricalFaults",flags).GetValue(h),vehicles=count,candidate=candidate,warmed=warm,initial_tm=initialTm,initial_ur=initialUr,release_input=Marshal.ReadByte(loc,0x8c),requested_step=step,brake_seconds=brakeCycles*.1,actual_ur_step=initialUr-heldUr,actual_tm_step=initialTm-finalTm,held_ur=heldUr,ur_after_30_s=settledUr,final_ur=finalUr,tm_after_30_s=settledTm,final_tm=finalTm,tm_min_after_30_s=minTm,tm_max_after_30_s=maxTm,start_tc=startTc,final_tc=finalTc,min_tc_after_30_s=minTc,rows=rows};string json=new JavaScriptSerializer().Serialize(result);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Trainer_relay_hold_"+count+"_"+args[0]+(candidate?"_candidate":"_baseline")+(warm?"_warm":"")+(electrical?"_electrical":"")+(ro1?"_ro1":"")+(headpl?"_headpl":"")+(vr483a?"_vr483a":"")+(testRelease?"_release":"")+(zr20?"_zr20":"")+(secs1?"_secs1":"")+(pilot1?"_pilot1":"")+".json"),json);Console.WriteLine("step="+step+" candidate="+candidate+" UR="+heldUr+"->"+finalUr+" TM="+finalTm+" TC="+finalTc+" TMspan="+(maxTm-minTm)+" release="+releaseCycles*.1);return 0;
}catch(Exception ex){Console.WriteLine(ex);return 1;}finally{if(experiment!=null)experiment.Dispose();h.Close();h.Dispose();}}
